+    ai->file_type = AOF_FILE_TYPE_INCR;
+    ai->file_name = sdscatprintf(sdsempty(), "%s.%lld%s", server.aof_filename, 
+                        ++am->curr_incr_aof_seq, INCR_AOF_SUFFIX);
+    ai->file_seq = am->curr_incr_aof_seq;
+    listAddNodeTail(am->incr_aof_list, ai);
+
+    am->dirty = 1;
+    return ai->file_name;
+}
