+        if (nwritten < 0) {
+            if (errno == EINTR) continue;
+            serverLog(LL_WARNING, "Error trying to write the temporary AOF manifest file %s: %s",
+                t_am_name, strerror(errno));
+
+            ret = C_ERR;
+            goto cleanup;
